.metrics article:last-child { border-right: 0; }
.metrics span, .metrics small { color: #7894a8; font-size: 12px; }
.metrics strong { font-size: 34px; letter-spacing: -.04em; margin: auto 0 5px; }
.panel { margin-top: 24px; border: 1px solid #294154; border-radius: 16px; background: #0b1927cc; min-height: 330px; }
.panel-title { padding: 24px 28px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #294154; }
h2 { margin: 0; font-size: 22px; letter-spacing: -.025em; }
.panel-title .eyebrow { margin-bottom: 6px; }
.panel-title code { color: #8fe3cf; background: #112638; padding: 9px 12px; border-radius: 7px; }
.empty { text-align: center; padding: 48px 20px; color: #7894a8; }
.mesh { width: 46px; height: 46px; display: grid; place-items: center; border-radius: 14px; background: #112638; color: #8fe3cf; margin: auto; font-size: 24px; }
.empty h3 { color: #e9f0f7; margin: 15px 0 7px; }
.empty p { margin: 0; font-size: 14px; }
.row { display: grid; grid-template-columns: 1.4fr .6fr 1fr .8fr; gap: 18px; align-items: center; padding: 18px 28px; border-bottom: 1px solid #203749; }
.row div { display: flex; flex-direction: column; gap: 4px; }
.row span, .row time { color: #7894a8; font-size: 11px; }
.row code { color: #a9c4d5; letter-spacing: 0; }
@media (max-width: 720px) { main { width: min(100% - 28px, 1180px); } header { grid-template-columns: 1fr; padding-top: 52px; } .health { width: fit-content; } .metrics { grid-template-columns: 1fr; } .metrics article { border-right: 0; border-bottom: 1px solid #294154; } .metrics article:last-child { border-bottom: 0; } .panel-title code { display: none; } .row { grid-template-columns: 1fr 1fr; } }

