const uniqueDigest = () => `sha256:${(++digestCounter).toString(16).padStart(64, '0')}`;

async function registerArtifact(app: App, name: string, version = '1.0.0') {
  const response = await app.inject({
    method: 'POST', url: '/api/v1/artifacts',
